from h34 import *
M=mcq;F=tf;S=short;N=num
numberline('c3-skip3.svg',0,30,3,[(0,3,'+3'),(3,6,'+3'),(6,9,'+3'),(9,12,'+3'),(12,15,'+3')],'Skip jumping by 3')
chapter(3,'maths','raksha-bandhan','Raksha Bandhan',
 ('Making rakhis for Atya','Gopal and Dhara are getting ready for Raksha Bandhan because their Atya is coming. They make rakhis, buy laddoos and jalebis, count plants in a garden and play a skip-jumping game. Along the way they discover that many problems are about equal groups.'),
 [('Equal groups and multiplication',['Each rakhi needs 1 flower, 2 threads and 4 beads. To make 5 rakhis we need 5 flowers, 10 threads and 20 beads.','We can find 10 threads by adding 2 + 2 + 2 + 2 + 2. This is 5 groups of 2, which we write as 5 times 2, or 5 × 2 = 10.','Multiplication is a quick way to write repeated addition of equal groups. 5 × 4 = 20 means 4 + 4 + 4 + 4 + 4.','A box of laddoos holds 3 rows of 3, so 3 × 3 = 9. Two boxes make 2 × 9 = 18, and the same 18 laddoos can also be seen as 6 groups of 3, so 6 × 3 = 18.','We can group the same objects in different ways. 8 rows of 6 plants and 6 rows of 8 plants make the same number, 48, so 8 × 6 = 6 × 8.']),
  ('Sharing equally and division',['Dhara wants to give 18 laddoos equally to 9 people. She gives one to each person, then another, and checks how many are left.','After two rounds nothing is left, so each person gets 2. We write 18 ÷ 9 = 2.','Division means sharing a number equally into groups, or finding how many equal groups we can make.','Kaju katlis work the same way. 20 kaju katlis shared among 5 plates is 20 ÷ 5 = 4 each, and we can check by multiplying, 5 × 4 = 20.','If each cycle needs 2 wheels, 12 wheels can fit 12 ÷ 2 = 6 cycles.']),
  ('Skip jumping and times tables',['On a number track, Dhara jumps from 0 by 3 each time. She lands on 3, 6, 9, 12 and so on. Skip jumping is repeated addition.','After 1 jump she is at 3, after 2 jumps at 6 = 2 × 3 and after 3 jumps at 9 = 3 × 3. These numbers make the times-3 table.','Every times table is a pattern of skip jumps. The times-2 table goes 2, 4, 6, 8, 10, and the times-5 table goes 5, 10, 15, 20, 25.','We can build the times-6 table by skip jumping by 6, or by adding 6 each time.','Mithu draws sticks and counts the crossing points to make a times table. The sticks show that 3 × 5 is 5 + 5 + 5 = 15.']),
  ('Using tables to solve problems',['If 4 jalebis are given to each of 9 people, we need 9 × 4 = 36 jalebis. 24 jalebis are not enough.','To buy enough jalebis for 9 people, Dhara should buy 36, so she needs 12 more.','The table of 10 is easy because 10 × 4 = 40. The table of 5 ends in 0 or 5.','Multiplication and division are partners. If 6 × 4 = 24, then 24 ÷ 4 = 6 and 24 ÷ 6 = 4.'])],
 [('Gopal makes 6 rakhis. Each rakhi needs 4 beads. How many beads does he need?',[('There are 6 equal groups of 4 beads.','Equal groups mean multiplication.'),('4 + 4 + 4 + 4 + 4 + 4 = 24, or 6 × 4 = 24.','Repeated addition and multiplication give the same answer.'),('He needs 24 beads.','Check with skip jumps of 4: 4, 8, 12, 16, 20, 24.')]),
  ('18 laddoos are shared equally among 9 people. How many does each person get?',[('Sharing equally means divide: 18 ÷ 9.','We split 18 into 9 equal parts.'),('Give 1 to each person: 9 are used and 9 are left. Give 1 more to each: nothing is left.','Two rounds of sharing.'),('Each person gets 2 laddoos.','Check: 9 × 2 = 18.')]),
  ('Dhara skip jumps by 3 from 0. Where does she land after 7 jumps?',[('7 jumps of 3 means 7 × 3.','Skip jumps are repeated addition.'),('3, 6, 9, 12, 15, 18, 21.','Counting seven landings.'),('She lands on 21.','7 × 3 = 21.')])],
 ('Explain how multiplication and division are connected using 3 × 4 = 12.',['3 groups of 4 make 12','12 divided into 3 equal groups gives 4 each','12 divided into groups of 4 gives 3 groups','Repeated addition 4 + 4 + 4 = 12'],['Division makes a number bigger','Multiplication is a different thing from adding']),
 ['Multiplication is repeated addition of equal groups, so 5 × 4 means 4 + 4 + 4 + 4 + 4.','Division is sharing equally, so 18 ÷ 9 = 2 each.','Skip jumping on a number track builds the times tables.','The order of numbers in multiplication does not change the answer, 8 × 6 = 6 × 8.','Multiplication and division are partners, 6 × 4 = 24 and 24 ÷ 4 = 6.'],
 [M('1',1,'What does 5 × 4 mean?','5 groups of 4',[('4 groups of 5 only','Both groups give 20, but the sentence says 5 groups of 4'),('5 + 4','That is 9')],'5 × 4 is 4 + 4 + 4 + 4 + 4.'),
  N('2',1,'2 + 2 + 2 + 2 + 2 = ?',10,'Five groups of 2 is 5 × 2 = 10.',[(8,'You added only four 2s'),(7,'Add 2 each time')]),
  N('3',1,'3 × 3 = ?',9,'Three groups of 3 make 9.',[(6,'3 + 3 is only 6'),(33,'This is multiplication, not writing side by side')]),
  N('4',1,'18 ÷ 9 = ?',2,'9 × 2 = 18, so 18 ÷ 9 = 2.',[(9,'Check: 9 × 9 is 81'),(3,'9 × 3 is 27')]),
  N('5',2,'A cycle has 2 wheels. How many cycles use 12 wheels?',6,'12 ÷ 2 = 6.',[(10,'10 cycles need 20 wheels'),(24,'Divide 12 by 2')]),
  N('6',2,'Skip jumping by 3 from 0, where is the 5th landing?',15,'3, 6, 9, 12, 15.',[(12,'That is the 4th landing'),(18,'That is the 6th landing')]),
  N('7',2,'9 people each get 4 jalebis. How many jalebis are needed?',36,'9 × 4 = 36.',[(13,'You added 9 + 4'),(24,'24 jalebis are 6 people only')]),
  N('8',2,'8 × 6 = ?',48,'8 × 6 and 6 × 8 are the same, 48.',[(42,'7 × 6 is 42'),(54,'9 × 6 is 54')]),
  F('9',2,'8 × 6 gives a different answer from 6 × 8.',False,'Both are 48. We can group the same objects in two ways.'),
  N('10',2,'20 kaju katlis are shared equally among 5 plates. How many on each plate?',4,'20 ÷ 5 = 4.',[(5,'5 × 5 = 25'),(15,'20 - 5 = 15, not division')]),
  M('11',3,'If 6 × 4 = 24, which is also true?','24 ÷ 4 = 6',[('24 ÷ 4 = 4','4 × 4 = 16'),('24 - 4 = 6','That is 20')],'Multiplication and division undo each other.'),
  N('12',3,'The times-5 table: 5, 10, 15, 20, ?',25,'Add 5 each time.',[(24,'Jump by 5 from 20'),(30,'That is the next one after 25')])],
 svgs=[('c3-skip3','A number line from 0 to 30 with five jumps of 3','Each jump of 3 is one more group of 3.')],
 keep=['multiplication','division','times table'])
